mapper.select:
SELECT /* LGVATT00022.retrieveOsKPI */ kor.SUBSIDIARY_CODE ,kor.VENDOR_CODE ,VM.VENDOR_NAME AS VENDOR_NAME ,kor.TIME_AND_ATTENDANCE_YYYYMM ,kor.ORGANIZATION_ID ,om.ORG_NAME_LOCAL AS ORG_NAME ,kor.ITEM_NO ,kos.ITEM_NAME ,kor.PERFECT_TARGET ,kor.PERFECT_POINT ,kor.ACTUAL_TARGET ,kor.ACTUAL_POINT ,kos.CRITERIA ,kor.REASON_DESC ,kor.CREATION_USER_ID ,kor.CREATION_DATE ,kor.LAST_UPDATE_USER_ID ,kor.LAST_UPDATE_DATE FROM TB_PAY_KPI_OS_REQUEST kor LEFT OUTER JOIN TB_VENDOR_MASTER VM ON (kor.VENDOR_CODE = VM.VENDOR_CODE) LEFT OUTER JOIN ORG_MASTER om ON (om.ORGANIZATION_ID = kor.ORGANIZATION_ID) LEFT OUTER JOIN TB_PAY_KPI_OS_STANDARD kos ON (kos.ITEM_NO = kor.ITEM_NO) WHERE 1=1 AND kor.SUBSIDIARY_CODE = #{subsidiaryCode}
AND kor.REQUEST_NO = #{requestNo}
AND kor.approval_request_id = #{requestMasterId} ORDER BY kor.ITEM_NO ASC

mapper.update:
	 MERGE /* LGVATT00022.saveOsKPI */ INTO TB_PAY_KPI_OS_REQUEST KOR
     USING DUAL
             ON (     
                  	  KOR.REQUEST_CODE = #{requestCode}
                  AND KOR.APPROVAL_REQUEST_ID = #{approvalRequestId}
                  AND KOR.TIME_AND_ATTENDANCE_YYYYMM = #{timeAndAttendanceYyyymm}
                  AND KOR.VENDOR_CODE = #{vendorCode}
                  AND KOR.ORGANIZATION_ID = #{organizationId}
                  AND KOR.ITEM_NO = #{itemNo}
                )
       WHEN MATCHED THEN
            UPDATE SET                         
                    CONFIRM_FLAG						   = 'Y'
                    ,PROGRESS_STATUS_CODE				   = (SELECT status_code FROM lgcom_approval_request_n WHERE request_master_id = KOR.approval_request_id AND request_code = KOR.request_code) 
                    ,LAST_UPDATE_USER_ID                   = #{sessionUserId}
                    ,LAST_UPDATE_DATE                      = SYSDATE
       WHEN NOT MATCHED THEN
            INSERT 
                   ( 
                    REQUEST_NO
                   ,REQUEST_SEQ_NO 
                   ,REQUEST_DATE
                   ,SUBSIDIARY_CODE
                   ,TIME_AND_ATTENDANCE_YYYYMM
                   ,VENDOR_CODE
                   ,ORGANIZATION_ID
                   ,ITEM_NO
                   ,PERFECT_TARGET
                   ,PERFECT_POINT
                   ,ACTUAL_TARGET
                   ,ACTUAL_POINT
                   ,REASON_DESC
                   ,APPROVAL_REQUEST_ID
                   ,REQUEST_CODE
                   ,PROGRESS_STATUS_CODE
                   ,CONFIRM_FLAG                   
                   ,CREATION_USER_ID
                   ,CREATION_DATE
                   ,LAST_UPDATE_USER_ID
                   ,LAST_UPDATE_DATE
                    )VALUES(
                    #{requestNo}
                   ,SQ_TB_PAY_KPI_OS_REQUEST.NEXTVAL
                   ,SYSDATE
                   ,#{subsidiaryCode} 
                   ,#{timeAndAttendanceYyyymm}
                   ,#{vendorCode}
                   ,#{organizationId}
                   ,#{itemNo}
                   ,#{perfectTarget}
                   ,#{perfectPoint}
                   ,#{actualTarget}
                   ,#{actualPoint}
                   ,#{reasonDesc}
                   ,#{approvalRequestId}
                   ,#{requestCode}
                   ,'20'
                   ,'N'                     
                   ,#{sessionUserId}
                   ,SYSDATE
                   ,#{sessionUserId}
                   ,SYSDATE
                       )

	UPDATE TB_PAY_KPI_OS_REQUEST KOR
	   SET KOR.PROGRESS_STATUS_CODE	  = (SELECT status_code FROM lgcom_approval_request_n WHERE request_master_id = KOR.approval_request_id AND request_code = KOR.request_code) 
          ,KOR.LAST_UPDATE_USER_ID      = #{sessionUserId}
          ,KOR.LAST_UPDATE_DATE         = SYSDATE
	 WHERE KOR.SUBSIDIARY_CODE 		  = #{LGVHR_PROJECT_SESSION.subsidiaryCode} 
	   AND KOR.REQUEST_CODE 			  = #{requestCode}
       AND KOR.APPROVAL_REQUEST_ID 	  = #{approvalRequestId}

DELETE FROM TB_PAY_KPI_OS_REQUEST ATT_F
 WHERE ATT_F.SUBSIDIARY_CODE = #{subsidiaryCode} 
   AND ATT_F.REQUEST_SEQ_NO = #{requestSeqNo}

mapper.select:
SELECT
EM.FULL_NAME_LOCAL AS requestor_info ,(SELECT common_code_name FROM LGCOM_COMMON_CODE_MULTI_LANG_C WHERE code_type_code = 'LGCOM_APPROVAL_REQ_STATUS_CODE' AND language_code = NVL('en','en') AND common_code = ATT_F.PROGRESS_STATUS_CODE) AS status_name ,TO_CHAR(ATT_F.LAST_UPDATE_DATE, 'DD/MM/YYYY') AS request_date , ATT_F.PROGRESS_STATUS_CODE as startus_code
FROM TB_PAY_KPI_OS_REQUEST ATT_F LEFT OUTER JOIN EMP_MASTER EM ON (ATT_F.EMPLOYEE_NO = EM.EMPLOYEE_NUMBER) LEFT OUTER JOIN tb_att_result_n tar ON (tar.employee_no = ATT_F.EMPLOYEE_NO AND TAR.time_and_attendance_date = ATT_F.TIME_AND_ATTENDANCE_DATE) WHERE 1=1 AND ATT_F.TIME_AND_ATTENDANCE_DATE = TO_DATE(#{timeAndAttendanceDate}, 'DD/MM/YYYY') AND ATT_F.EMPLOYEE_NO = #{employeeNo} AND ATT_F.SUBSIDIARY_CODE = #{subsidiaryCode} AND ATT_F.LAST_UPDATE_USER_ID = #{sessionUserId}


    SELECT COUNT(*) AS dup_count
	FROM   TB_PAY_KPI_OS_REQUEST kos
	WHERE  1 = 1
	AND    kos.time_and_attendance_yyyymm = #{timeAndAttendanceYyyymm}
	AND    kos.progress_status_code IN ('20', '30', '40') --기등록 건( 50: Cancel 제외)
	AND    NVL(kos.confirm_flag, 'N') <> 'R'   -- Rejected
	AND    kos.vendor_code = #{vendorCode}
	AND    kos.organization_id = #{orgName}
